const (
	Version = "5570362"
	Commit  = "5570362e88f0b23eb901a0ea856e77c3fd66ea95"
	Built   = "2026-08-10 23:10 UTC by build.sh"
)

var banner = `
 _ __ _____   _(_)__  _____
| '__/ _ \ \ / / \ \ / / _ \
| | |  __/\ V /| |\ V /  __/
|_|  \___| \_/ |_| \_/ \___|

Example:
  revive -config c.toml -formatter friendly -exclude a.go -exclude b.go ./...
`

type Failure struct {
	Severity        string   `json:"Severity"`
	Failure         string   `json:"Failure"`
	RuleName        string   `json:"RuleName"`
	Category        string   `json:"Category"`
	Position        Position `json:"Position"`
	Confidence      float64  `json:"Confidence"`
	ReplacementLine string   `json:"ReplacementLine"`
}

type Position struct {
	Start PositionInfo `json:"Start"`
	End   PositionInfo `json:"End"`
}

type PositionInfo struct {
	Filename string `json:"Filename"`
	Offset   int    `json:"Offset"`
	Line     int    `json:"Line"`
	Column   int    `json:"Column"`
}

type Config struct {
	Severity              string
	Confidence             float64
	ErrorCode             int
	WarningCode           int
	IgnoreGeneratedHeader bool
	Rules                 map[string]*RuleConfig
}

type RuleConfig struct {
	Disabled   bool
	Severity   string
	Confidence float64
	HasConfidence bool
	Exclude    []string
	Arguments  []interface{}
}

type excludeValue []string

func (e *excludeValue) String() string { return strings.Join(*e, ",") }
func (e *excludeValue) Set(v string) error {
	*e = append(*e, v)
	return nil
}

func main() {
	flag.Usage = func() {
		fmt.Fprint(os.Stdout, banner)
		fmt.Fprint(os.Stdout, "\n")
		fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
		flag.PrintDefaults()
	}

	var configPath string
	var formatter string
	var maxOpenFiles int
	var setExitStatus bool
	var versionFlag bool
	var excludes excludeValue

	flag.StringVar(&configPath, "config", "", "path to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)")
	flag.Var(&excludes, "exclude", "list of globs which specify files to be excluded (i.e. -exclude foo/...)")
	flag.StringVar(&formatter, "formatter", "", "formatter to be used for the output (i.e. -formatter stylish)")
	flag.IntVar(&maxOpenFiles, "max_open_files", 0, "maximum number of open files at the same time")
	flag.BoolVar(&setExitStatus, "set_exit_status", false, "set exit status to 1 if any issues are found, overwrites errorCode and warningCode in config")
	flag.BoolVar(&versionFlag, "version", false, "get revive version")

	// Handle help flags manually before parsing to ensure banner
	// flag package handles -h and --help automatically, but we need custom banner
	flag.Parse()

	if versionFlag {
		fmt.Printf("Version:\t%s\nCommit:\t\t%s\nBuilt\t\t%s\n", Version, Commit, Built)
		os.Exit(0)
	}

	// If no args and no flags that require action, check if help was requested via -h
	// flag already handled help, but we need to ensure that running without args does nothing
	// Check for unknown formatter etc handled later

	// Determine formatter default
	if formatter == "" {
		formatter = "default"
	}
	// Validate formatter
	validFormatters := map[string]bool{
		"default": true, "json": true, "ndjson": true, "plain": true, "unix": true, "stylish": true, "friendly": true, "checkstyle": true, "sarif": true,
	}
	if !validFormatters[formatter] {
		fmt.Fprintf(os.Stderr, "formatting - getting formatter: unknown formatter %s\n", formatter)
		os.Exit(1)
	}

	// Load config
	cfg, err := loadConfig(configPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, "cannot read the config file")
		os.Exit(1)
	}

	args := flag.Args()
	// If no args, exit 0 with no output (as original does)
	if len(args) == 0 {
		// Original with no args and no formatter gave no output, exit 0
		os.Exit(0)
	}

	// Resolve files
	files, err := resolveFiles(args, []string(excludes))
	if err != nil {
		// err already contains full message to print
		fmt.Fprint(os.Stderr, err.Error())
		if !strings.HasSuffix(err.Error(), "\n") {
			fmt.Fprintln(os.Stderr)
		}
		os.Exit(1)
	}

	// Filter files by global exclude
	filtered := []string{}
	cwd, _ := os.Getwd()
	for _, f := range files {
		if isExcluded(f, []string(excludes), cwd) {
			continue
		}
		filtered = append(filtered, f)
	}
	files = filtered

	// Lint files
	var allFailures []Failure
	for _, file := range files {
		failures, err := lintFile(file, cfg)
		if err != nil {
			// parse error? ignore?
			continue
		}
		allFailures = append(allFailures, failures...)
	}

	// Apply confidence threshold, severity, etc. - already done in lintFile per config?
	// Need to determine exit code based on severities
	hasError := false
	hasWarning := false
	for _, f := range allFailures {
		if f.Severity == "error" {
			hasError = true
		} else {
			hasWarning = true
		}
	}

	exitCode := 0
	if setExitStatus {
		if len(allFailures) > 0 {
			exitCode = 1
		} else {
			exitCode = 0
		}
	} else {
		if hasError {
			exitCode = cfg.ErrorCode
		} else if hasWarning {
			exitCode = cfg.WarningCode
		} else {
			exitCode = 0
		}
	}

	// Format output
	output, err := formatOutput(allFailures, formatter, cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "formatting - getting formatter: unknown formatter %s\n", formatter)
		os.Exit(1)
	}
	if output != "" {
		fmt.Print(output)
		// For some formatters, original adds extra newline? We handle in format functions
	}
	os.Exit(exitCode)
}

func loadConfig(path string) (*Config, error) {
	cfg := &Config{
		Severity:    "warning",
		Confidence:  0.8,
		ErrorCode:   0,
		WarningCode: 0,
		Rules:       make(map[string]*RuleConfig),
	}
	// If path provided, must exist
	if path != "" {
		data, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		if err := parseTOML(string(data), cfg); err != nil {
			return nil, err
		}
		return cfg, nil
	}
	// Search default locations
	// Check XDG_CONFIG_HOME
	xdg := os.Getenv("XDG_CONFIG_HOME")
	if xdg != "" {
		p := filepath.Join(xdg, "revive.toml")
		if _, err := os.Stat(p); err == nil {
			data, err := os.ReadFile(p)
			if err != nil {
				return nil, err
			}
			if err := parseTOML(string(data), cfg); err != nil {
				return nil, err
			}
			return cfg, nil
		}
		// XDG set but file not found -> try HOME? According to observed, if XDG set, only check XDG, not HOME
		// But if XDG file not found, we should return default config (no file)
		return cfg, nil
	}
	// Check HOME/revive.toml
	home := os.Getenv("HOME")
	if home == "" {
		home = os.Getenv("USERPROFILE") // windows fallback
		if home == "" {
			// try user home dir via os
			if h, err := os.UserHomeDir(); err == nil {
				home = h
			}
		}
	}
	if home != "" {
		p := filepath.Join(home, "revive.toml")
		if _, err := os.Stat(p); err == nil {
			data, err := os.ReadFile(p)
			if err != nil {
				return nil, err
			}
			if err := parseTOML(string(data), cfg); err != nil {
				return nil, err
			}
			return cfg, nil
		}
	}
	// No config file found, return default with default rules enabled
	// Mark that no config was loaded, so we will use default enabled rules
	// We indicate this by leaving Rules empty but handling in lintFile
	// To distinguish, we set a flag: if no config file, we enable default rules
	// We can set a special marker: if len(Rules)==0 and path=="" and no file found, we treat as default
	// But if config file was empty (no rules), we should have no rules enabled.
	// How to distinguish? We need to know if config file was loaded or not.
	// If no file was loaded, we populate default rules.
	// If file was loaded but has no rules, we keep empty.
	// So here we are in no file case, populate defaults
	cfg.Rules = getDefaultRules()
	return cfg, nil
}

func getDefaultRules() map[string]*RuleConfig {
	// Default enabled rules as observed: exported, package-comments, var-naming, empty-block, unused-parameter, unreachable-code
	// Possibly also others, but we include these
	m := make(map[string]*RuleConfig)
	for _, r := range []string{"exported", "package-comments", "var-naming", "empty-block", "unused-parameter", "unreachable-code"} {
		m[r] = &RuleConfig{Disabled: false}
	}
	return m
}

func parseTOML(data string, cfg *Config) error {
	lines := strings.Split(data, "\n")
	currentRule := ""
	for _, raw := range lines {
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		// Remove comments after #
		if idx := strings.Index(line, "#"); idx != -1 {
			// need to ensure # not inside string
			// simplistic: if line contains '"', ignore comment stripping
			if !strings.Contains(line[:idx], `"`) {
				line = strings.TrimSpace(line[:idx])
			}
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section := strings.TrimSpace(line[1 : len(line)-1])
			if strings.HasPrefix(section, "rule.") {
				currentRule = strings.TrimPrefix(section, "rule.")
				if _, ok := cfg.Rules[currentRule]; !ok {
					cfg.Rules[currentRule] = &RuleConfig{}
				}
			} else {
				currentRule = ""
			}
			continue
		}
		// key = value
		eq := strings.Index(line, "=")
		if eq == -1 {
			continue
		}
		key := strings.TrimSpace(line[:eq])
		val := strings.TrimSpace(line[eq+1:])
		// Parse value
		if currentRule != "" {
			rc := cfg.Rules[currentRule]
			switch strings.ToLower(key) {
			case "disabled":
				b, _ := parseBool(val)
				rc.Disabled = b
			case "severity":
				s := parseString(val)
				rc.Severity = s
			case "confidence":
				f, _ := strconv.ParseFloat(parseString(val), 64)
				// also handle numeric without quotes
				if f == 0 {
					f, _ = strconv.ParseFloat(strings.Trim(val, `"`), 64)
				}
				rc.Confidence = f
				rc.HasConfidence = true
			case "exclude":
				arr := parseArray(val)
				rc.Exclude = arr
			case "arguments":
				// parse array of values
				arr := parseArrayRaw(val)
				rc.Arguments = arr
			case "disabled": // already
			}
		} else {
			switch strings.ToLower(key) {
			case "severity":
				cfg.Severity = parseString(val)
			case "confidence":
				f, _ := strconv.ParseFloat(parseString(val), 64)
				if f == 0 {
					f, _ = strconv.ParseFloat(strings.Trim(val, `"`), 64)
				}
				cfg.Confidence = f
			case "errorcode":
				i, _ := strconv.Atoi(parseString(val))
				if i == 0 {
					i, _ = strconv.Atoi(strings.Trim(val, `"`))
					if i == 0 {
						i, _ = strconv.Atoi(val)
					}
				}
				cfg.ErrorCode = i
			case "warningcode":
				i, _ := strconv.Atoi(parseString(val))
				if i == 0 {
					i, _ = strconv.Atoi(strings.Trim(val, `"`))
					if i == 0 {
						i, _ = strconv.Atoi(val)
					}
				}
				cfg.WarningCode = i
			case "ignoregeneratedheader":
				b, _ := parseBool(val)
				cfg.IgnoreGeneratedHeader = b
			case "version":
				// ignore
			}
		}
	}
	// Post-process: if config file had rules, then only those rules are enabled; others disabled
	// If no rules were defined, then Rules will be empty, meaning no rules enabled (as observed for empty config)
	// So we don't add defaults.
	return nil
}

func parseBool(s string) (bool, error) {
	s = strings.ToLower(strings.TrimSpace(s))
	s = strings.Trim(s, `"`)
	if s == "true" {
		return true, nil
	}
	if s == "false" {
		return false, nil
	}
	return false, fmt.Errorf("invalid bool")
}

func parseString(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		inner := s[1 : len(s)-1]
		// handle escaped?
		return inner
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return s[1 : len(s)-1]
	}
	return strings.Trim(s, `"`)
}

func parseArray(s string) []string {
	s = strings.TrimSpace(s)
	if !strings.HasPrefix(s, "[") || !strings.HasSuffix(s, "]") {
		return nil
	}
	inner := strings.TrimSpace(s[1 : len(s)-1])
	if inner == "" {
		return nil
	}
	// Split by comma, handling quotes
	var res []string
	var cur bytes.Buffer
	inQuote := false
	quoteChar := byte(0)
	for i := 0; i < len(inner); i++ {
		c := inner[i]
		if (c == '"' || c == '\'') && (i == 0 || inner[i-1] != '\\') {
			if !inQuote {
				inQuote = true
				quoteChar = c
			} else if c == quoteChar {
				inQuote = false
			}
			cur.WriteByte(c)
		} else if c == ',' && !inQuote {
			part := strings.TrimSpace(cur.String())
			if part != "" {
				res = append(res, parseString(part))
			}
			cur.Reset()
		} else {
			cur.WriteByte(c)
		}
	}
	part := strings.TrimSpace(cur.String())
	if part != "" {
		res = append(res, parseString(part))
	}
	return res
}

func parseArrayRaw(s string) []interface{} {
	strs := parseArray(s)
	var res []interface{}
	for _, v := range strs {
		// try parse as int
		if i, err := strconv.Atoi(v); err == nil {
			res = append(res, i)
		} else if f, err := strconv.ParseFloat(v, 64); err == nil {
			res = append(res, f)
		} else {
			res = append(res, v)
		}
	}
	// Also handle numeric array like [80] without quotes
	if len(res) == 0 {
		inner := strings.TrimSpace(s[1 : len(s)-1])
		if inner != "" {
			parts := strings.Split(inner, ",")
			for _, p := range parts {
				p = strings.TrimSpace(p)
				if p == "" {
					continue
				}
				if i, err := strconv.Atoi(p); err == nil {
					res = append(res, i)
				} else {
					res = append(res, p)
				}
			}
		}
	}
	return res
}

func resolveFiles(args []string, excludes []string) ([]string, error) {
	var files []string
	cwd, _ := os.Getwd()
	for _, arg := range args {
		if strings.Contains(arg, "...") {
			// pattern like ./..., pkg/..., /tmp/...
			base := strings.Split(arg, "...")[0]
			base = strings.TrimSuffix(base, "/")
			if base == "" || base == "." {
				base = "."
			}
			// If base is absolute or relative, resolve
			var searchRoot string
			if filepath.IsAbs(base) {
				searchRoot = base
			} else {
				searchRoot = filepath.Join(cwd, base)
			}
			// Check if searchRoot exists, if not, try to find go packages via go list? For now, walk
			if _, err := os.Stat(searchRoot); err != nil {
				// If not exists, try to treat as package pattern and error?
				// For original, if pattern is like "github.com/...", it would use go list
				// For our simple, if not found, return error similar to original's import error?
				// We'll just walk from cwd if base is "." else error
				if base == "." {
					searchRoot = cwd
				} else {
					// Try to find packages via walking cwd and matching pattern prefix
					// For simplicity, walk cwd recursively and collect .go files
					// But need to handle pattern like "pkg1/..." where pkg1 is under cwd
					// We'll just attempt to walk cwd and filter by prefix
					// If still not found, error
					searchRoot = cwd
				}
			}
			err := filepath.Walk(searchRoot, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if info.IsDir() {
					name := info.Name()
					if name == "vendor" || strings.HasPrefix(name, ".") {
						return filepath.SkipDir
					}
					return nil
				}
				if strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go") {
					// Check if path matches pattern prefix when pattern is not "..." generic
					// For arg like "pkg1/...", we should only include files under pkg1
					if base != "." && base != "" {
						rel, err := filepath.Rel(cwd, path)
						if err != nil {
							return nil
						}
						// Check if rel has prefix base
						// base may be like "pkg1" or "pkg1/"
						prefix := strings.TrimPrefix(base, "./")
						prefix = strings.TrimPrefix(prefix, "/")
						// For absolute base, compute differently
						if filepath.IsAbs(arg) {
							// Check absolute prefix
							if !strings.HasPrefix(path, base) {
								return nil
							}
						} else {
							if !strings.HasPrefix(rel, prefix) {
								return nil
							}
						}
					}
					// For display, use relative path if under cwd
					display := path
					if rel, err := filepath.Rel(cwd, path); err == nil && !strings.HasPrefix(rel, "..") {
						display = rel
					}
					// But for absolute args, keep absolute?
					// We'll store display as relative if possible, else absolute
					files = append(files, display)
				}
				return nil
			})
			if err != nil {
				return nil, err
			}
			// If no files found and arg was like "./..." in a directory with go.mod, maybe we should still return something?
			// If no files found, original might still succeed with no output
			continue
		}
		// Check if arg is file
		if info, err := os.Stat(arg); err == nil {
			if info.IsDir() {
				// walk directory
				err := filepath.Walk(arg, func(path string, info os.FileInfo, err error) error {
					if err != nil {
						return nil
					}
					if !info.IsDir() && strings.HasSuffix(path, ".go") {
						files = append(files, path)
					}
					return nil
				})
				if err != nil {
					return nil, err
				}
			} else {
				// file
				if strings.HasSuffix(arg, ".go") {
					files = append(files, arg)
				} else {
					// not go file, maybe package?
					// For original, if arg is file without .go but is package, it would use go/packages
					// We'll treat as error
					return nil, fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: import %q: cannot import absolute path\n", arg)
				}
			}
		} else {
			// arg does not exist as file
			// Check if it's an absolute path ending with .go -> original error for absolute path
			if filepath.IsAbs(arg) && strings.HasSuffix(arg, ".go") {
				return nil, fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: import %q: cannot import absolute path\n", arg)
			}
			// Try to see if it's a package pattern without ...
			// For simplicity, try to find files matching package
			// If arg contains "/" and not file, maybe it's a package import path
			// We'll try to walk cwd for matching directory
			pkgPath := filepath.Join(cwd, arg)
			if info, err := os.Stat(pkgPath); err == nil && info.IsDir() {
				filepath.Walk(pkgPath, func(path string, info os.FileInfo, err error) error {
					if err == nil && !info.IsDir() && strings.HasSuffix(path, ".go") {
						rel, _ := filepath.Rel(cwd, path)
						files = append(files, rel)
					}
					return nil
				})
			} else {
				// Return error as original does for dots
				return nil, fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: import %q: cannot import absolute path\n", arg)
			}
		}
	}
	// Deduplicate
	seen := make(map[string]bool)
	var uniq []string
	for _, f := range files {
		if !seen[f] {
			seen[f] = true
			uniq = append(uniq, f)
		}
	}
	return uniq, nil
}

func isExcluded(path string, patterns []string, cwd string) bool {
	if len(patterns) == 0 {
		return false
	}
	// Normalize path
	absPath := path
	if !filepath.IsAbs(path) {
		absPath = filepath.Join(cwd, path)
	}
	relPath := path
	if filepath.IsAbs(path) {
		if rel, err := filepath.Rel(cwd, path); err == nil {
			relPath = rel
		}
	} else {
		relPath = path
	}
	for _, pat := range patterns {
		pat = strings.TrimSpace(pat)
		if pat == "" {
			continue
		}
		if strings.HasSuffix(pat, "/...") {
			prefix := strings.TrimSuffix(pat, "/...")
			prefix = strings.TrimPrefix(prefix, "./")
			// Check against relPath and absPath
			if strings.HasPrefix(relPath, prefix) || strings.HasPrefix(absPath, prefix) {
				return true
			}
			// Also check if pat is like "pkg1/..." and relPath is "pkg1/a.go"
			if strings.HasPrefix(relPath, prefix+"/") || relPath == prefix {
				return true
			}
			if strings.HasPrefix(absPath, filepath.Join(cwd, prefix)) {
				return true
			}
		} else {
			// Use fnmatch
			if matched, _ := filepath.Match(pat, path); matched {
				return true
			}
			if matched, _ := filepath.Match(pat, relPath); matched {
				return true
			}
			if matched, _ := filepath.Match(pat, absPath); matched {
				return true
			}
			if matched, _ := filepath.Match(pat, filepath.Base(path)); matched {
				return true
			}
			// Also try with pattern containing * like "*.go" should match basename?
			if pat == "*.go" {
				if strings.HasSuffix(filepath.Base(path), ".go") {
					// But original didn't match absolute path with *.go, so we need to not match absolute?
					// For relative path, it should match files in current dir only, not subdirs
					// We'll check if relPath contains "/" -> not match
					if !strings.Contains(relPath, "/") && strings.HasSuffix(relPath, ".go") {
						return true
					}
				}
			}
			// Handle patterns like "foo/..."
			if strings.Contains(pat, "*") {
				if ok, _ := filepath.Match(pat, relPath); ok {
					return true
				}
				if ok, _ := filepath.Match(pat, absPath); ok {
					return true
				}
			}
			// Exact match
			if pat == path || pat == relPath || pat == absPath {
				return true
			}
		}
	}
	return false
}

func lintFile(filename string, cfg *Config) ([]Failure, error) {
	// Check if file exists
	content, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}
	// Check generated header
	if cfg.IgnoreGeneratedHeader {
		lines := strings.Split(string(content), "\n")
		if len(lines) > 0 && strings.Contains(lines[0], "Code generated") && strings.Contains(lines[0], "DO NOT EDIT") {
			return nil, nil
		}
		// Also check second line? Original checks first comment block
		// We'll check first line only
	}

	fset := token.NewFileSet()
	// Parse file
	f, err := parser.ParseFile(fset, filename, content, parser.ParseComments)
	if err != nil {
		// If parse error, return empty
		return nil, nil
	}

	// Build disabled map for directives
	disabledMap := buildDisabledMap(string(content), cfg)

	var failures []Failure

	// Helper to check if rule is enabled
	isEnabled := func(rule string) bool {
		if rc, ok := cfg.Rules[rule]; ok {
			if rc.Disabled {
				return false
			}
			return true
		}
		// If rule not in config, it is disabled (when config file was loaded)
		// But if we are in default config case (getDefaultRules), then we have entries for default rules
		// So this works
		return false
	}

	// Helper to check rule exclude
	isRuleExcluded := func(rule string, filename string) bool {
		if rc, ok := cfg.Rules[rule]; ok && len(rc.Exclude) > 0 {
			cwd, _ := os.Getwd()
			for _, pat := range rc.Exclude {
				if isExcluded(filename, []string{pat}, cwd) {
					return true
				}
			}
		}
		return false
	}

	// Helper to get rule severity and confidence
	getSeverity := func(rule string) string {
		if rc, ok := cfg.Rules[rule]; ok && rc.Severity != "" {
			return rc.Severity
		}
		if cfg.Severity != "" {
			return cfg.Severity
		}
		return "warning"
	}
	getConfidenceThreshold := func(rule string) float64 {
		if rc, ok := cfg.Rules[rule]; ok && rc.HasConfidence {
			return rc.Confidence
		}
		return cfg.Confidence
	}

	// Collect failures per rule
	var all []Failure

	if isEnabled("package-comments") && !isRuleExcluded("package-comments", filename) {
		fails := checkPackageComments(f, fset, filename)
		for _, fl := range fails {
			fl.Severity = getSeverity("package-comments")
			fl.Category = "comments"
			fl.RuleName = "package-comments"
			// Confidence for this rule is 1
			fl.Confidence = 1
			if fl.Confidence >= getConfidenceThreshold("package-comments") && !isDisabledAtLine(disabledMap, fl.Position.Start.Line, "package-comments") {
				all = append(all, fl)
			}
		}
	}
	if isEnabled("exported") && !isRuleExcluded("exported", filename) {
		fails := checkExported(f, fset, filename)
		for _, fl := range fails {
			fl.Severity = getSeverity("exported")
			fl.Category = "comments"
			fl.RuleName = "exported"
			// Confidence varies: for missing comment 1, for wrong form 0.8? We'll use 1 for now, but need to differentiate
			// Set based on message
			if strings.Contains(fl.Failure, "should be of the form") {
				if strings.Contains(fl.Failure, "to match its exported status") {
					fl.Confidence = 1
				} else {
					fl.Confidence = 0.8
				}
			} else {
				fl.Confidence = 1
			}
			if fl.Confidence >= getConfidenceThreshold("exported") && !isDisabledAtLine(disabledMap, fl.Position.Start.Line, "exported") {
				all = append(all, fl)
			}
		}
	}
	if isEnabled("var-naming") && !isRuleExcluded("var-naming", filename) {
		fails := checkVarNaming(f, fset, filename)
		for _, fl := range fails {
			fl.Severity = getSeverity("var-naming")
			fl.Category = "naming"
			fl.RuleName = "var-naming"
			// Confidence already set per failure: 1 for MixedCaps, 0.9 for underscores
			// Need to set threshold
			if fl.Confidence >= getConfidenceThreshold("var-naming") && !isDisabledAtLine(disabledMap, fl.Position.Start.Line, "var-naming") {
				all = append(all, fl)
			}
		}
	}
	if isEnabled("empty-block") && !isRuleExcluded("empty-block", filename) {
		fails := checkEmptyBlock(f, fset, filename)
		for _, fl := range fails {
			fl.Severity = getSeverity("empty-block")
			fl.Category = "logic"
			fl.RuleName = "empty-block"
			fl.Confidence = 1
			if fl.Confidence >= getConfidenceThreshold("empty-block") && !isDisabledAtLine(disabledMap, fl.Position.Start.Line, "empty-block") {
				all = append(all, fl)
			}
		}
	}
	if isEnabled("unused-parameter") && !isRuleExcluded("unused-parameter", filename) {
		fails := checkUnusedParameter(f, fset, filename)
		for _, fl := range fails {
			fl.Severity = getSeverity("unused-parameter")
			fl.Category = "bad practice"
			fl.RuleName = "unused-parameter"
			fl.Confidence = 1
			if fl.Confidence >= getConfidenceThreshold("unused-parameter") && !isDisabledAtLine(disabledMap, fl.Position.Start.Line, "unused-parameter") {
				all = append(all, fl)
			}
		}
	}
	if isEnabled("unreachable-code") && !isRuleExcluded("unreachable-code", filename) {
		fails := checkUnreachableCode(f, fset, filename)
		for _, fl := range fails {
			fl.Severity = getSeverity("unreachable-code")
			fl.Category = "logic"
			fl.RuleName = "unreachable-code"
			fl.Confidence = 1
			if fl.Confidence >= getConfidenceThreshold("unreachable-code") && !isDisabledAtLine(disabledMap, fl.Position.Start.Line, "unreachable-code") {
				all = append(all, fl)
			}
		}
	}
	if isEnabled("line-length-limit") && !isRuleExcluded("line-length-limit", filename) {
		// Get limit from arguments, default 80?
		limit := 80
		if rc, ok := cfg.Rules["line-length-limit"]; ok && len(rc.Arguments) > 0 {
			if v, ok := rc.Arguments[0].(int); ok {
				limit = v
			} else if s, ok := rc.Arguments[0].(string); ok {
				if i, err := strconv.Atoi(s); err == nil {
					limit = i
				}
			} else if f, ok := rc.Arguments[0].(float64); ok {
				limit = int(f)
			}
		}
		fails := checkLineLength(string(content), filename, limit)
		for _, fl := range fails {
			fl.Severity = getSeverity("line-length-limit")
			fl.Category = "style"
			fl.RuleName = "line-length-limit"
			fl.Confidence = 1
			if fl.Confidence >= getConfidenceThreshold("line-length-limit") && !isDisabledAtLine(disabledMap, fl.Position.Start.Line, "line-length-limit") {
				all = append(all, fl)
			}
		}
	}
	// For other rules enabled but not implemented, return no failures

	// Sort failures? For json we preserve as collected (which is rule order)
	// For other formatters we will sort later, but we can sort here by position for consistency?
	// Let's not sort here, let formatter sort if needed

	failures = all

	// Apply global confidence threshold already done per rule, but also need to handle severity override per failure?
	// Already set

	return failures, nil
}

func buildDisabledMap(content string, cfg *Config) map[int]map[string]bool {
	lines := strings.Split(content, "\n")
	disabled := make(map[string]bool) // current disabled rules, empty means none; if global disabled, use special key "*"
	globalDisabled := false
	nextLineDisabled := make(map[string]bool)
	nextGlobal := false
	result := make(map[int]map[string]bool)

	for i, line := range lines {
		lineno := i + 1
		// Initialize map for this line based on current state
		m := make(map[string]bool)
		if globalDisabled {
			m["*"] = true
		}
		for k, v := range disabled {
			if v {
				m[k] = true
			}
		}
		// Apply nextLine disabled from previous line's directive
		if nextGlobal {
			m["*"] = true
		}
		for k := range nextLineDisabled {
			m[k] = true
		}
		// Save
		result[lineno] = m

		// Reset nextLine for next iteration (only affects next line)
		nextLineDisabled = make(map[string]bool)
		nextGlobal = false

		// Check for directives in this line
		// Look for //revive:disable etc
		trim := strings.TrimSpace(line)
		// Find comment part
		idx := strings.Index(line, "//")
		comment := ""
		if idx != -1 {
			comment = line[idx:]
		} else {
			// also handle /* */
			if strings.Contains(line, "/*") {
				comment = line
			}
		}
		if strings.Contains(comment, "revive:disable") || strings.Contains(comment, "revive:enable") {
			// Determine type
			isDisable := strings.Contains(comment, "revive:disable")
			isEnable := strings.Contains(comment, "revive:enable")
			// Check for disable-next-line
			isNextLine := strings.Contains(comment, "revive:disable-next-line") || strings.Contains(comment, "revive:enable-next-line")
			// Extract rule part after colon
			// Format: //revive:disable[:rule1,rule2]
			// Find the directive
			var directive string
			if isNextLine {
				// find "revive:disable-next-line" or "revive:enable-next-line"
				if strings.Contains(comment, "revive:disable-next-line") {
					directive = "revive:disable-next-line"
					isDisable = true
					isEnable = false
				} else {
					directive = "revive:enable-next-line"
					isDisable = false
					isEnable = true
				}
			} else if isDisable {
				directive = "revive:disable"
			} else if isEnable {
				directive = "revive:enable"
			}
			// Find after directive
			pos := strings.Index(comment, directive)
			rest := ""
			if pos != -1 {
				rest = comment[pos+len(directive):]
				rest = strings.TrimSpace(rest)
				// rest may start with ":" then rule list
				if strings.HasPrefix(rest, ":") {
					rest = strings.TrimPrefix(rest, ":")
					rest = strings.TrimSpace(rest)
					// rest is rule list, may be comma separated or space?
					// Split by comma and space
					parts := regexp.MustCompile(`[,\s]+`).Split(rest, -1)
					var rules []string
					for _, p := range parts {
						p = strings.TrimSpace(p)
						if p != "" {
							// Remove any trailing comment terminators
							p = strings.Trim(p, "*/ ")
							rules = append(rules, p)
						}
					}
					if isNextLine {
						if len(rules) == 0 {
							// disable/enable all for next line
							if isDisable {
								nextGlobal = true
							} else {
								// enable all for next line means clear? For next line only, we set global enable?
								// But enable-next-line not standard, ignore
							}
						} else {
							for _, r := range rules {
								if isDisable {
									nextLineDisabled[r] = true
								} else {
									// enable means remove from disabled for next line? But next line's disabled is computed from current state, so enabling for next line means ensure not disabled
									// We'll handle by not adding to nextLineDisabled
								}
							}
						}
					} else {
						if len(rules) == 0 {
							if isDisable {
								globalDisabled = true
								disabled = make(map[string]bool)
							} else {
								globalDisabled = false
								disabled = make(map[string]bool)
							}
						} else {
							for _, r := range rules {
								if isDisable {
									disabled[r] = true
								} else {
									delete(disabled, r)
								}
							}
						}
					}
				} else {
					// No colon, means all rules
					if isNextLine {
						if isDisable {
							nextGlobal = true
						} else {
							// enable next line all?
						}
					} else {
						if isDisable {
							globalDisabled = true
							disabled = make(map[string]bool)
						} else {
							globalDisabled = false
							disabled = make(map[string]bool)
						}
					}
				}
			}
		}
		// After handling directive, the next line's disabled map will be set
		// For current line, the directive affects next lines, not current (except for disable-next-line which affects next)
		// So we already set result for current line before updating state, which is correct for //revive:disable starting next line?
		// Actually //revive:disable should affect next lines, not current line. Our result for current line is before updating, so current line not disabled, correct.
		// For //revive:disable-next-line, it should affect next line only, which we set via nextLineDisabled for next iteration, correct.
	}
	return result
}

func isDisabledAtLine(m map[int]map[string]bool, line int, rule string) bool {
	if m == nil {
		return false
	}
	if dis, ok := m[line]; ok {
		if dis["*"] {
			return true
		}
		if dis[rule] {
			return true
		}
	}
	return false
}

