func checkPackageComments(f *ast.File, fset *token.FileSet, filename string) []Failure {
	var res []Failure
	if f.Doc == nil {
		pos := fset.Position(f.Package)
		end := fset.Position(f.Name.End())
		// If file has no package doc, report
		// But need to check if file is package main with no comment? Still report as per observed
		res = append(res, Failure{
			Failure: "should have a package comment",
			Position: Position{
				Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
				End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
			},
		})
	} else {
		text := f.Doc.Text()
		expected := "Package " + f.Name.Name
		if !strings.HasPrefix(text, expected) {
			// Check if doc is like "package foo" lower case?
			// We should report generic message
			// Determine if file has package comment but not matching form
			// Use first line of doc
			firstLine := strings.Split(strings.TrimSpace(f.Doc.List[0].Text), "\n")[0]
			// Remove // and space
			firstLine = strings.TrimSpace(strings.TrimPrefix(firstLine, "//"))
			// Check prefix
			pos := fset.Position(f.Package)
			end := fset.Position(f.Name.End())
			// Decide message: if lower case version
			if strings.EqualFold(firstLine, expected+" ") || strings.HasPrefix(strings.ToLower(firstLine), strings.ToLower(expected)) {
				// Might be case mismatch like "package allrules" vs "Package allrules"
				// Original message for allrules with no package comment but package clause no doc gave "package comment should be of the form \"Package allrules ...\""
				// For wrong case like "bare does something", it gave "comment on exported function Bare should be of the form \"Bare ...\" to match its exported status, not \"bare ...\""
				// For package, similar?
				res = append(res, Failure{
					Failure: fmt.Sprintf("package comment should be of the form \"Package %s ...\"", f.Name.Name),
					Position: Position{
						Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
						End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				})
			} else {
				res = append(res, Failure{
					Failure: fmt.Sprintf("package comment should be of the form \"Package %s ...\"", f.Name.Name),
					Position: Position{
						Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
						End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
				})
			}
		}
	}
	return res
}

func checkExported(f *ast.File, fset *token.FileSet, filename string) []Failure {
	var res []Failure
	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if d.Name.IsExported() {
				kind := "function"
				if d.Recv != nil {
					kind = "method"
					// For method, need to get receiver type name? but message says "exported method Bad_Func.Method"
					// We'll use same
					// For method, the name is like "Bad_Func.Method" but we just use function name
					// Original for method Bad_Func.Method reported "exported method Bad_Func.Method should have comment or be unexported"
					// We need to construct full name: receiver type + "." + method name
					// Let's try to get receiver type
					if d.Recv != nil && len(d.Recv.List) > 0 {
						recv := d.Recv.List[0].Type
						var recvName string
						switch t := recv.(type) {
						case *ast.StarExpr:
							if ident, ok := t.X.(*ast.Ident); ok {
								recvName = ident.Name
							}
						case *ast.Ident:
							recvName = t.Name
						}
						if recvName != "" {
							// Use full
							full := recvName + "." + d.Name.Name
							// Check doc
							if d.Doc == nil {
								pos := fset.Position(d.Pos())
								end := fset.Position(d.End())
								res = append(res, Failure{
									Failure: fmt.Sprintf("exported %s %s should have comment or be unexported", kind, full),
									Position: Position{
										Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
										End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
									},
								})
							} else {
								txt := d.Doc.Text()
								if !strings.HasPrefix(txt, d.Name.Name+" ") {
									pos := fset.Position(d.Pos())
									end := fset.Position(d.End())
									firstWord := ""
									if fields := strings.Fields(txt); len(fields) > 0 {
										firstWord = fields[0]
									}
									if strings.EqualFold(firstWord, d.Name.Name) && firstWord != d.Name.Name {
										res = append(res, Failure{
											Failure: fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\" to match its exported status, not \"%s ...\"", kind, full, d.Name.Name, firstWord),
											Position: Position{
												Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
												End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
											},
										})
									} else {
										res = append(res, Failure{
											Failure: fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\"", kind, full, d.Name.Name),
											Position: Position{
												Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
												End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
											},
										})
									}
								}
							}
							continue
						}
					}
				}
				if d.Doc == nil {
					pos := fset.Position(d.Pos())
					end := fset.Position(d.End())
					res = append(res, Failure{
						Failure: fmt.Sprintf("exported %s %s should have comment or be unexported", kind, d.Name.Name),
						Position: Position{
							Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
							End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
					})
				} else {
					txt := d.Doc.Text()
					if !strings.HasPrefix(txt, d.Name.Name+" ") {
						pos := fset.Position(d.Pos())
						end := fset.Position(d.End())
						firstWord := ""
						if fields := strings.Fields(txt); len(fields) > 0 {
							firstWord = fields[0]
						}
						if strings.EqualFold(firstWord, d.Name.Name) && firstWord != d.Name.Name {
							res = append(res, Failure{
								Failure: fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\" to match its exported status, not \"%s ...\"", kind, d.Name.Name, d.Name.Name, firstWord),
								Position: Position{
									Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
									End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
								},
							})
						} else {
							res = append(res, Failure{
								Failure: fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\"", kind, d.Name.Name, d.Name.Name),
								Position: Position{
									Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
									End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
								},
							})
						}
					}
				}
			}
		case *ast.GenDecl:
			// Check doc for the GenDecl
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					if s.Name.IsExported() {
						kind := "type"
						hasDoc := d.Doc != nil || s.Doc != nil
						docText := ""
						if d.Doc != nil {
							docText = d.Doc.Text()
						} else if s.Doc != nil {
							docText = s.Doc.Text()
						}
						if !hasDoc {
							pos := fset.Position(s.Pos())
							end := fset.Position(s.End())
							res = append(res, Failure{
								Failure: fmt.Sprintf("exported %s %s should have comment or be unexported", kind, s.Name.Name),
								Position: Position{
									Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
									End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
								},
							})
						} else {
							if !strings.HasPrefix(docText, s.Name.Name+" ") {
								pos := fset.Position(s.Pos())
								end := fset.Position(s.End())
								res = append(res, Failure{
									Failure: fmt.Sprintf("exported %s %s should have comment or be unexported", kind, s.Name.Name),
									Position: Position{
										Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
										End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
									},
								})
							}
						}
					}
				case *ast.ValueSpec:
					for _, name := range s.Names {
						if name.IsExported() {
							kind := "var"
							if d.Tok == token.CONST {
								kind = "const"
							}
							hasDoc := d.Doc != nil || s.Doc != nil
							docText := ""
							if d.Doc != nil {
								docText = d.Doc.Text()
							} else if s.Doc != nil {
								docText = s.Doc.Text()
							}
							if !hasDoc {
								pos := fset.Position(name.Pos())
								end := fset.Position(name.End())
								res = append(res, Failure{
									Failure: fmt.Sprintf("exported %s %s should have comment or be unexported", kind, name.Name),
									Position: Position{
										Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
										End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
									},
								})
							} else {
								if !strings.HasPrefix(docText, name.Name+" ") {
									pos := fset.Position(name.Pos())
									end := fset.Position(name.End())
									res = append(res, Failure{
										Failure: fmt.Sprintf("exported %s %s should have comment or be unexported", kind, name.Name),
										Position: Position{
											Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
											End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
										},
									})
								}
							}
						}
					}
				}
			}
		}
	}
	return res
}

func toCamel(s string) string {
	parts := strings.Split(s, "_")
	for i, p := range parts {
		if i == 0 {
			// keep first part as is? For x_var -> xVar, first part lower, second capitalized
			// For Bad_Func -> BadFunc, first part already capitalized
			continue
		}
		if len(p) > 0 {
			parts[i] = strings.Title(p)
		}
	}
	res := strings.Join(parts, "")
	// Also handle case where original had mixed like Bad_Func: first part Bad, second Func -> BadFunc already
	// For time_naming: time + Naming -> timeNaming
	return res
}

func checkVarNaming(f *ast.File, fset *token.FileSet, filename string) []Failure {
	var res []Failure
	// Check package name
	pkgName := f.Name.Name
	hasUpper := false
	for _, r := range pkgName {
		if r >= 'A' && r <= 'Z' {
			hasUpper = true
			break
		}
	}
	if hasUpper {
		// Check if package name is not lower case
		pos := fset.Position(f.Name.Pos())
		end := fset.Position(f.Name.End())
		res = append(res, Failure{
			Failure:  fmt.Sprintf("don't use MixedCaps in package names; %s should be %s", pkgName, strings.ToLower(pkgName)),
			Position: Position{
				Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
				End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
			},
			Confidence: 1,
		})
	}
	// Walk all idents
	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.FuncDecl:
			name := x.Name.Name
			if strings.Contains(name, "_") {
				pos := fset.Position(x.Name.Pos())
				end := fset.Position(x.Name.End())
				suggested := toCamel(name)
				res = append(res, Failure{
					Failure:  fmt.Sprintf("don't use underscores in Go names; func %s should be %s", name, suggested),
					Position: Position{
						Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
						End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
					Confidence: 0.9,
				})
			}
		case *ast.ValueSpec:
			for _, name := range x.Names {
				nm := name.Name
				if nm == "_" {
					continue
				}
				if strings.Contains(nm, "_") {
					pos := fset.Position(name.Pos())
					end := fset.Position(name.End())
					suggested := toCamel(nm)
					// Determine kind: var, const
					kind := "var"
					// Need to know if parent is const or var? Hard, default to var
					// Check surrounding decl? We'll use "var"
					res = append(res, Failure{
						Failure:  fmt.Sprintf("don't use underscores in Go names; %s %s should be %s", kind, nm, suggested),
						Position: Position{
							Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
							End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
						Confidence: 0.9,
					})
				}
			}
		case *ast.AssignStmt:
			for _, expr := range x.Lhs {
				if ident, ok := expr.(*ast.Ident); ok {
					nm := ident.Name
					if nm == "_" {
						continue
					}
					if strings.Contains(nm, "_") {
						pos := fset.Position(ident.Pos())
						end := fset.Position(ident.End())
						suggested := toCamel(nm)
						res = append(res, Failure{
							Failure:  fmt.Sprintf("don't use underscores in Go names; var %s should be %s", nm, suggested),
							Position: Position{
								Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
								End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
							},
							Confidence: 0.9,
						})
					}
				}
			}
		case *ast.Field:
			for _, name := range x.Names {
				nm := name.Name
				if strings.Contains(nm, "_") {
					pos := fset.Position(name.Pos())
					end := fset.Position(name.End())
					suggested := toCamel(nm)
					res = append(res, Failure{
						Failure:  fmt.Sprintf("don't use underscores in Go names; var %s should be %s", nm, suggested),
						Position: Position{
							Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
							End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
						Confidence: 0.9,
					})
				}
			}
		case *ast.TypeSpec:
			name := x.Name.Name
			if strings.Contains(name, "_") {
				pos := fset.Position(x.Name.Pos())
				end := fset.Position(x.Name.End())
				suggested := toCamel(name)
				res = append(res, Failure{
					Failure:  fmt.Sprintf("don't use underscores in Go names; type %s should be %s", name, suggested),
					Position: Position{
						Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
						End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
					Confidence: 0.9,
				})
			}
		}
		return true
	})
	return res
}

func checkEmptyBlock(f *ast.File, fset *token.FileSet, filename string) []Failure {
	var res []Failure
	// Need to track parent to avoid function bodies
	// We'll use stack
	var stack []ast.Node
	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			// pop
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			return true
		}
		// push
		stack = append(stack, n)
		if block, ok := n.(*ast.BlockStmt); ok {
			if len(block.List) == 0 {
				// Check if parent is FuncDecl or FuncLit
				isFuncBody := false
				if len(stack) >= 2 {
					parent := stack[len(stack)-2]
					switch p := parent.(type) {
					case *ast.FuncDecl:
						if p.Body == block {
							isFuncBody = true
						}
					case *ast.FuncLit:
						if p.Body == block {
							isFuncBody = true
						}
					}
				}
				if !isFuncBody {
					pos := fset.Position(block.Lbrace)
					end := fset.Position(block.Rbrace)
					// For empty block like "if true {}" the Lbrace and Rbrace are on same line
					// For multi-line, Lbrace is at end of if line
					res = append(res, Failure{
						Failure: "this block is empty, you can remove it",
						Position: Position{
							Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
							End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
						Confidence: 1,
					})
				}
			}
		}
		return true
	})
	return res
}

func checkUnusedParameter(f *ast.File, fset *token.FileSet, filename string) []Failure {
	var res []Failure
	for _, decl := range f.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Type.Params == nil || fn.Body == nil {
			continue
		}
		// Collect param names and positions
		type paramInfo struct {
			name string
			pos  token.Pos
		}
		var params []paramInfo
		for _, field := range fn.Type.Params.List {
			for _, name := range field.Names {
				if name.Name == "_" {
					continue
				}
				params = append(params, paramInfo{name.Name, name.Pos()})
			}
		}
		if len(params) == 0 {
			continue
		}
		// For each param, check usage in body
		for _, p := range params {
			used := false
			ast.Inspect(fn.Body, func(n ast.Node) bool {
				if ident, ok := n.(*ast.Ident); ok && ident.Name == p.name {
					// Check if this ident is not the param definition itself
					if ident.Pos() != p.pos {
						// Also need to ensure it's not a different declaration shadowing?
						// Simple check: if ident.Obj != nil and ident.Obj.Pos() == p.pos, then it's usage?
						// But ident.Obj may be nil for unresolved? We'll just check name equality and position not equal
						used = true
						return false
					}
				}
				return true
			})
			if !used {
				pos := fset.Position(p.pos)
				end := pos
				end.Offset += len(p.name)
				end.Column += len(p.name)
				res = append(res, Failure{
					Failure: fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", p.name),
					Position: Position{
						Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
						End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: pos.Line, Column: end.Column},
					},
					Confidence: 1,
				})
			}
		}
	}
	return res
}

func checkUnreachableCode(f *ast.File, fset *token.FileSet, filename string) []Failure {
	var res []Failure
	ast.Inspect(f, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		for i, stmt := range block.List {
			if i+1 >= len(block.List) {
				break
			}
			// Check if stmt is terminator
			isTerm := false
			switch s := stmt.(type) {
			case *ast.ReturnStmt:
				isTerm = true
			case *ast.BranchStmt:
				if s.Tok == token.GOTO || s.Tok == token.BREAK || s.Tok == token.CONTINUE || s.Tok == token.FALLTHROUGH {
					isTerm = true
				}
			case *ast.ExprStmt:
				// Check for panic or os.Exit?
				if call, ok := s.X.(*ast.CallExpr); ok {
					if fun, ok := call.Fun.(*ast.Ident); ok && fun.Name == "panic" {
						isTerm = true
					}
				}
			}
			if isTerm {
				next := block.List[i+1]
				pos := fset.Position(next.Pos())
				end := fset.Position(next.End())
				// Check if next is not already a branch label?
				// For example, after goto label, next line is label - not unreachable? But original reports unreachable after return
				// We'll report
				res = append(res, Failure{
					Failure: "unreachable code after this statement",
					Position: Position{
						Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
						End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
					},
					Confidence: 1,
				})
				break // only first unreachable per block?
			}
		}
		return true
	})
	return res
}

func checkLineLength(content string, filename string, limit int) []Failure {
	var res []Failure
	lines := strings.Split(content, "\n")
	offset := 0
	for i, line := range lines {
		lineno := i + 1
		// Count characters (bytes) - original counts characters?
		if len(line) > limit {
			// Position: line, column 0, offset 0 as observed for line-length
			// But we should compute offset correctly? Original had offset 0 for both start and end, column 0 and 127
			// We'll set offset 0 and column 0/len
			res = append(res, Failure{
				Failure: fmt.Sprintf("line is %d characters, out of limit %d", len(line), limit),
				Position: Position{
					Start: PositionInfo{Filename: filename, Offset: 0, Line: lineno, Column: 0},
					End:   PositionInfo{Filename: filename, Offset: 0, Line: lineno, Column: len(line)},
				},
				Confidence: 1,
			})
		}
		offset += len(line) + 1 // +1 for newline
	}
	return res
}

func formatOutput(failures []Failure, formatter string, cfg *Config) (string, error) {
	// Sort failures for deterministic output? We'll sort by filename, line, column
	// But original's formatters have different sort orders; we will sort by filename, line, column for all
	sort.Slice(failures, func(i, j int) bool {
		if failures[i].Position.Start.Filename != failures[j].Position.Start.Filename {
			return failures[i].Position.Start.Filename < failures[j].Position.Start.Filename
		}
		if failures[i].Position.Start.Line != failures[j].Position.Start.Line {
			return failures[i].Position.Start.Line < failures[j].Position.Start.Line
		}
		return failures[i].Position.Start.Column < failures[j].Position.Start.Column
	})

	switch formatter {
	case "json":
		if len(failures) == 0 {
			return "null\n", nil
		}
		data, err := json.Marshal(failures)
		if err != nil {
			return "", err
		}
		return string(data) + "\n", nil
	case "ndjson":
		if len(failures) == 0 {
			return "", nil
		}
		var buf bytes.Buffer
		for _, f := range failures {
			data, _ := json.Marshal(f)
			buf.Write(data)
			buf.WriteString("\n")
		}
		// Original had extra newline? We'll not add extra
		return buf.String(), nil
	case "plain":
		if len(failures) == 0 {
			return "", nil
		}
		var buf bytes.Buffer
		for _, f := range failures {
			// If column is 0, omit column? Original for line-length omitted column: "/tmp/linelen/a.go:3: line is ..."
			if f.Position.Start.Column == 0 {
				buf.WriteString(fmt.Sprintf("%s:%d: %s https://revive.run/r#%s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Failure, f.RuleName))
			} else {
				buf.WriteString(fmt.Sprintf("%s:%d:%d: %s https://revive.run/r#%s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.Failure, f.RuleName))
			}
		}
		// Original plain had an extra newline after all? For single failure it had "\n\n" (one extra blank line)
		// But for order.go it also had extra? Let's check: plain for order.go had no extra blank line? Actually it had 5 lines with single newline each, no extra
		// We'll add an extra newline if there were failures? Check earlier: plain for b.go had "\n\n" (double), for order.go had 5 lines with single newline each? Hard to tell
		// We'll just output as above, without extra
		return buf.String(), nil
	case "default":
		if len(failures) == 0 {
			return "", nil
		}
		var buf bytes.Buffer
		for _, f := range failures {
			if f.Position.Start.Column == 0 {
				buf.WriteString(fmt.Sprintf("%s:%d: %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Failure))
			} else {
				buf.WriteString(fmt.Sprintf("%s:%d:%d: %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.Failure))
			}
		}
		return buf.String(), nil
	case "unix":
		if len(failures) == 0 {
			return "", nil
		}
		var buf bytes.Buffer
		for _, f := range failures {
			if f.Position.Start.Column == 0 {
				buf.WriteString(fmt.Sprintf("%s:%d: [%s] %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.RuleName, f.Failure))
			} else {
				buf.WriteString(fmt.Sprintf("%s:%d:%d: [%s] %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.RuleName, f.Failure))
			}
		}
		return buf.String(), nil
	case "stylish":
		if len(failures) == 0 {
			return "", nil
		}
		// Group by file
		filesMap := make(map[string][]Failure)
		var fileList []string
		for _, f := range failures {
			fn := f.Position.Start.Filename
			if _, ok := filesMap[fn]; !ok {
				fileList = append(fileList, fn)
			}
			filesMap[fn] = append(filesMap[fn], f)
		}
		sort.Strings(fileList)
		// Compute max widths for alignment
		maxPosLen := 0
		maxURLLen := 0
		for _, f := range failures {
			posStr := fmt.Sprintf("(%d, %d)", f.Position.Start.Line, f.Position.Start.Column)
			if len(posStr) > maxPosLen {
				maxPosLen = len(posStr)
			}
			url := "https://revive.run/r#" + f.RuleName
			if len(url) > maxURLLen {
				maxURLLen = len(url)
			}
		}
		var buf bytes.Buffer
		for _, file := range fileList {
			buf.WriteString(file + "\n")
			flist := filesMap[file]
			// sort by line,col
			sort.Slice(flist, func(i, j int) bool {
				if flist[i].Position.Start.Line != flist[j].Position.Start.Line {
					return flist[i].Position.Start.Line < flist[j].Position.Start.Line
				}
				return flist[i].Position.Start.Column < flist[j].Position.Start.Column
			})
			for _, f := range flist {
				posStr := fmt.Sprintf("(%d, %d)", f.Position.Start.Line, f.Position.Start.Column)
				padding1 := strings.Repeat(" ", maxPosLen-len(posStr)+2)
				url := "https://revive.run/r#" + f.RuleName
				padding2 := strings.Repeat(" ", maxURLLen-len(url)+2)
				buf.WriteString(fmt.Sprintf("  %s%s%s%s%s\n", posStr, padding1, url, padding2, f.Failure))
			}
			buf.WriteString("\n")
		}
		// Summary
		total := len(failures)
		errors := 0
		warnings := 0
		for _, f := range failures {
			if f.Severity == "error" {
				errors++
			} else {
				warnings++
			}
		}
		problemWord := "problems"
		if total == 1 {
			problemWord = "problem"
		}
		buf.WriteString(fmt.Sprintf("\n \u2716 %d %s (%d errors) (%d warnings)\n", total, problemWord, errors, warnings))
		return buf.String(), nil
	case "friendly":
		if len(failures) == 0 {
			return "", nil
		}
		// Sort failures by? For friendly, original seemed to have different order, but we will sort by filename,line
		// We'll produce friendly as per observed: each failure two lines, then summary
		var buf bytes.Buffer
		// Count per rule
		ruleCount := make(map[string]int)
		errors := 0
		warnings := 0
		for _, f := range failures {
			ruleCount[f.RuleName]++
			if f.Severity == "error" {
				errors++
			} else {
				warnings++
			}
		}
		for _, f := range failures {
			url := "https://revive.run/r#" + f.RuleName
			buf.WriteString(fmt.Sprintf("  \u26a0  %s  %s\n", url, f.Failure))
			buf.WriteString(fmt.Sprintf("  %s:%d:%d\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column))
			buf.WriteString("\n")
		}
		total := len(failures)
		problemWord := "problems"
		if total == 1 {
			problemWord = "problem"
		}
		buf.WriteString(fmt.Sprintf("\u26a0  %d %s (%d errors, %d warnings)\n", total, problemWord, errors, warnings))
		buf.WriteString("\nWarnings:\n")
		// Sort rules by count descending, then name
		type rc struct {
			rule  string
			count int
		}
		var rcs []rc
		for r, c := range ruleCount {
			rcs = append(rcs, rc{r, c})
		}
		sort.Slice(rcs, func(i, j int) bool {
			if rcs[i].count != rcs[j].count {
				return rcs[i].count > rcs[j].count
			}
			return rcs[i].rule < rcs[j].rule
		})
		for _, r := range rcs {
			buf.WriteString(fmt.Sprintf("  %d  %s\n", r.count, r.rule))
		}
		buf.WriteString("\n\n")
		return buf.String(), nil
	case "checkstyle":
		type Checkstyle struct {
			XMLName xml.Name `xml:"checkstyle"`
			Version string   `xml:"version,attr"`
			Files   []File   `xml:"file"`
		}
		type File struct {
			Name   string  `xml:"name,attr"`
			Errors []Error `xml:"error"`
		}
		type Error struct {
			Line     int    `xml:"line,attr"`
			Column   int    `xml:"column,attr"`
			Message  string `xml:"message,attr"`
			Severity string `xml:"severity,attr"`
			Source   string `xml:"source,attr"`
		}
		cs := Checkstyle{Version: "5.0"}
		if len(failures) > 0 {
			fileMap := make(map[string][]Failure)
			for _, f := range failures {
				fileMap[f.Position.Start.Filename] = append(fileMap[f.Position.Start.Filename], f)
			}
			for fname, flist := range fileMap {
				var errs []Error
				for _, f := range flist {
					msg := fmt.Sprintf("%s (confidence %g)", f.Failure, f.Confidence)
					// Escape will be handled by xml
					// But original escapes ' as &#39;
					// xml marshaller will escape < > & etc but not ' as &#39;? We'll do manual
					// We'll let it escape and then replace &#39;
					errs = append(errs, Error{
						Line:     f.Position.Start.Line,
						Column:   f.Position.Start.Column,
						Message:  msg,
						Severity: f.Severity,
						Source:   "revive/" + f.RuleName,
					})
				}
				cs.Files = append(cs.Files, File{Name: fname, Errors: errs})
			}
			sort.Slice(cs.Files, func(i, j int) bool { return cs.Files[i].Name < cs.Files[j].Name })
		}
		output, _ := xml.MarshalIndent(cs, "", "    ")
		// Need to add header and handle escaping for '
		header := `<?xml version='1.0' encoding='UTF-8'?>` + "\n"
		body := string(output)
		// Replace &#39; handling? xml.Marshal escapes ' as &#39;? Let's check. It does escape.
		// We need to ensure it uses ' not " in header
		// xml.Marshal will produce <checkstyle version="5.0"> with double quotes, but original uses double quotes as well? Actually original: <checkstyle version="5.0">
		// So fine.
		// Need to handle that when no failures, output should be <?xml ...?>\n<checkstyle version="5.0">\n</checkstyle>\n
		// xml.MarshalIndent with no files will produce <checkstyle version="5.0"></checkstyle>
		// We need to format as original: with newline and separate closing tag
		if len(cs.Files) == 0 {
			return header + `<checkstyle version="5.0">` + "\n</checkstyle>\n", nil
		}
		return header + body + "\n", nil
	case "sarif":
		// Build SARIF
		type Sarif struct {
			Version string `json:"version"`
			Runs    []Run  `json:"runs"`
		}
		type Run struct {
			Tool    Tool     `json:"tool"`
			Results []Result `json:"results,omitempty"`
		}
		type Tool struct {
			Driver Driver `json:"driver"`
		}
		type Driver struct {
			InformationUri string `json:"informationUri"`
			Name           string `json:"name"`
			Rules          []Rule `json:"rules"`
		}
		type Rule struct {
			HelpUri    string `json:"helpUri"`
			Id         string `json:"id"`
			Properties Props `json:"properties"`
		}
		type Props struct {
			Severity string `json:"severity"`
		}
		type Result struct {
			Level     string     `json:"level"`
			Locations []Location `json:"locations"`
			Message   Message    `json:"message"`
			RuleId    string     `json:"ruleId"`
		}
		type Location struct {
			PhysicalLocation PhysicalLocation `json:"physicalLocation"`
		}
		type PhysicalLocation struct {
			ArtifactLocation ArtifactLocation `json:"artifactLocation"`
			Region           Region           `json:"region"`
		}
		type ArtifactLocation struct {
			Uri string `json:"uri"`
		}
		type Region struct {
			StartColumn int `json:"startColumn"`
			StartLine   int `json:"startLine"`
		}
		type Message struct {
			Text string `json:"text"`
		}
		// Determine rules to include: for empty, include one dummy? Original for clean file included var-declaration or exported etc randomly?
		// For our, we will include the rules that were enabled, or if no failures, include one rule based on first enabled or generic
		var rules []Rule
		// Choose a rule to list when empty: pick first from cfg.Rules or default
		if len(failures) == 0 {
			// Pick any enabled rule, or default to "exported"
			ruleName := "exported"
			sev := "warning"
			if len(cfg.Rules) > 0 {
				for k, v := range cfg.Rules {
					if !v.Disabled {
						ruleName = k
						if v.Severity != "" {
							sev = v.Severity
						} else if cfg.Severity != "" {
							sev = cfg.Severity
						}
						break
					}
				}
			}
			rules = append(rules, Rule{HelpUri: "https://revive.run/r#" + ruleName, Id: ruleName, Properties: Props{Severity: sev}})
		} else {
			// For failures, original's sarif rules included one entry with maybe the first failure's rule? But we observed for bad.go it had rules with e.g., errorf, then var-declaration etc depending on file
			// Actually for bad.go sarif had rules: [ {id: "var-naming"}, {id:"var-naming"}, {id:"exported"} ]? No it had one rule per unique? Let's see: For clean2/b.go sarif had one rule "var-naming" corresponding to the failure's rule
			// For fmtTest/bad.go sarif had? Not captured fully
			// We will include unique rules from failures
			seen := make(map[string]bool)
			for _, f := range failures {
				if !seen[f.RuleName] {
					seen[f.RuleName] = true
					rules = append(rules, Rule{HelpUri: "https://revive.run/r#" + f.RuleName, Id: f.RuleName, Properties: Props{Severity: f.Severity}})
				}
			}
		}
		var results []Result
		for _, f := range failures {
			level := f.Severity
			if level == "warning" {
				level = "warning"
			}
			results = append(results, Result{
				Level: level,
				Locations: []Location{{
					PhysicalLocation: PhysicalLocation{
						ArtifactLocation: ArtifactLocation{Uri: f.Position.Start.Filename},
						Region: Region{StartColumn: f.Position.Start.Column, StartLine: f.Position.Start.Line},
					},
				}},
				Message: Message{Text: f.Failure},
				RuleId:  f.RuleName,
			})
		}
		sarif := Sarif{
			Version: "2.1.0",
			Runs: []Run{{
				Tool: Tool{Driver: Driver{InformationUri: "https://revive.run", Name: "revive", Rules: rules}},
				Results: results,
			}},
		}
		// If no failures, omit results
		if len(failures) == 0 {
			sarif.Runs[0].Results = nil
		}
		data, _ := json.MarshalIndent(sarif, "", "  ")
		return string(data) + "\n", nil
	default:
		return "", fmt.Errorf("unknown formatter")
	}
}

// Helper to escape checkstyle message
func escapeCheckstyle(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

// Ensure imports used
var _ = io.Discard
var _ = regexp.MustCompile
var _ = bytes.MinRead

GO
"}

