					}
				}
			}
		case *ast.Field:
			for _, name := range x.Names {
				nm := name.Name
				if strings.Contains(nm, "_") {
					pos := fset.Position(name.Pos())
					end := fset.Position(name.End())
					suggested := toCamel(nm)
					res = append(res, Failure{
