						Position: Position{
							Start: PositionInfo{Filename: filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column},
							End:   PositionInfo{Filename: filename, Offset: end.Offset, Line: end.Line, Column: end.Column},
						},
						Confidence: 0.9,
					})
				}
			}
		case *ast.TypeSpec:
			name := x.Name.Name
			if strings.Contains(name, "_") {
