		if failures[i].Position.Start.Filename != failures[j].Position.Start.Filename {
			return failures[i].Position.Start.Filename < failures[j].Position.Start.Filename
		}
		if failures[i].Position.Start.Line != failures[j].Position.Start.Line {
			return failures[i].Position.Start.Line < failures[j].Position.Start.Line
